voltage = 198

if voltage < 180:
    status = "CRITICAL: undervoltage"
elif voltage < 207:
    status = "WARNING: low"
elif voltage <= 253:
    status = "normal"
else:
    status = "WARNING: overvoltage"

print(voltage, status)

def energy_cost(kwh, rate=68.5):
    cost = kwh * rate
    return round(cost, 2)

print(energy_cost(350))
print(energy_cost(350, rate=50))
