readings = [12.5, 14.0, 13.2, 0.0, 15.1]

total = 0
for r in readings:
    total += r

print("Total:", total)
print("Average:", total / len(readings))

for i, r in enumerate(readings):
    if r == 0:
        print("Zero reading at position", i)

readings = {"MTR-1": 12.5, "MTR-2": 14.0, "MTR-3": 0.0}

readings["MTR-4"] = 9.8
print(readings.get("MTR-9", "unknown meter"))

for meter, kwh in readings.items():
    print(meter, kwh)

def average(readings):
    try:
        return sum(readings) / len(readings)
    except ZeroDivisionError:
        return None

print(average([10, 12, 14]))
print(average([]))

